import{_ as t}from"./chunks/3dots_menu.BrLPqWzo.js";import{_ as o,a as r,b as a,c as s,d as i,e as n,f as l,g as d,h as c,i as h,j as m,k as p,l as u,m as g,n as y,o as b,p as f,q as w}from"./chunks/3DM-CU.Cv4Q9_Tx.js";import{_,o as k,c as v,a3 as x}from"./chunks/framework.g9mfNVRQ.js";const F=JSON.parse('{"title":"3 Dots menu","description":"","frontmatter":{},"headers":[],"relativePath":"use/3dotsmenu.md","filePath":"use/3dotsmenu.md"}'),S={name:"use/3dotsmenu.md"};function q(z,e,D,P,I,T){return k(),v("div",null,[...e[0]||(e[0]=[x('<img src="'+t+'" style="zoom:75%;"><h3 id="reminders" tabindex="-1">Reminders <a class="header-anchor" href="#reminders" aria-label="Permalink to &quot;Reminders&quot;">​</a></h3><p>You can set up various reminders with this menu, just touch the + button bottom right.</p><img src="'+o+'" style="zoom:75%;"><p>Name it as you like</p><img src="'+r+'" style="zoom:75%;"><p>The music note icon <code>1</code> allows you to select the sound that will ring when the reminder activates.<br> You can set the reminder to trigger in a defined delay from now using the selection <code>2</code> hours, days, weeks and the numeric value. If you set Repeat it will repeat with the same delay, for example you can set it to alarm every 2 weeks.<br> You can set it to trigger only during weekdays or weekends, or both <code>3</code>.<br> If you select Alternating, it will display different messages <code>4</code> and you can swap them with the double arrow icon.<br> You can have the reminder spoken when it triggers.<br> If you select Chime only, the reminder will not need to be acknowledged: it will ring only once. Without this selection it will sound repeatedly until dismissed.<br> At Home Only will make the reminder trigger only when the phone is connected to your home Wi-Fi, see below how to set it.</p><p>Toggling the checkboxes will give hints on the actual function.</p><p>Once set, you can change the reminder title by touching it.</p><p>You can modify it with a long touch.</p><p>Swiping a reminder to the left snoozes it by 30 minutes (default) and you can change that delay with the button below.</p><img src="'+a+'" style="zoom:75%;"><p>Swiping a reminder to the right allows you to either <code>1</code> snooze it by the time selected below (from 15 minutes to 1 week) or <code>3</code> delete it. If you change your mind you can undo the changes <code>2</code>.</p><img src="'+s+'" style="zoom:75%;"><p>Another 3 dots menu is available top right.</p><img src="'+i+'" style="zoom:75%;"><p>You can define your home network with Set Home Network, this is used when the reminder is set to At Home Only.<br> You can disable the reminders during the night, you can also disable all alerts in which case the next checkbox will allow you to restart (enable back all reminders) the next morning.</p><h3 id="emergency-messages" tabindex="-1">Emergency Messages <a class="header-anchor" href="#emergency-messages" aria-label="Permalink to &quot;Emergency Messages&quot;">​</a></h3><p>xDrip can automatically send text messages in certain conditions to alert others. This obviously requires phone network coverage and a provisioned SIM card. Phone location must be authorized for xDrip to use this feature.</p><img src="'+n+'" style="zoom:75%;"><p>In order to set it up you need to first add a contact, then optionally put a name and finally decide upon which emergency situation will trigger the SMS.</p><img src="'+l+'" style="zoom:75%;"><p>You can then send a test message to verify correct functioning of the emergency system.</p><img src="'+d+'" style="zoom:75%;"><h3 id="import-export-features" tabindex="-1">Import Export Features <a class="header-anchor" href="#import-export-features" aria-label="Permalink to &quot;Import Export Features&quot;">​</a></h3><p>In this menu you can find various options to import (only the entire xDrip database) or export data.</p><img src="'+c+'" style="zoom:75%;"><p>See <a href="./../troubleshoot/reinstall.html#backup">here</a> for database and settings import/export.</p><p>You can export data starting from a certain date to now, in SiDiary format. The file will be saved in <code>/storage/emulated/0/xDrip</code> as a zip file containing the comma-separated values list of data.</p><img src="'+h+'" style="zoom:75%;"><h3 id="crowd-sources-translation" tabindex="-1">Crowd-sourced translation <a class="header-anchor" href="#crowd-sources-translation" aria-label="Permalink to &quot;Crowd-sourced translation {#crowd-sources-translation}&quot;">​</a></h3><p>xDrip translation relies on volunteers with <a href="https://crowdin.com/project/xdrip" target="_blank" rel="noreferrer">Crowdin</a>.<br> You&#39;re welcome to contribute, contact the managers at the bottom of the page.</p><img src="'+m+'" style="zoom:75%;"><h3 id="events-log" tabindex="-1">Events Log <a class="header-anchor" href="#events-log" aria-label="Permalink to &quot;Events Log&quot;">​</a></h3><p>Events log gives many insights into what xDrip is doing, you can add more traces by adding <a href="./lesscommon.html#extra-logging-settings">tags</a>.</p><img src="'+p+'" style="zoom:75%;"><p>You can also filter the items displayed by selecting the desired log or events with the check boxes above the list.<br> When sharing screenshots of the error log make sure to enable all and manually hide personal information (credentials, serial numbers, ...)</p><p><code>High</code> displays errors</p><img src="'+u+'" style="zoom:75%;"><p><code>Mid</code> displays traces</p><img src="'+g+'" style="zoom:75%;"><p><code>Low</code> displays all others (lower importance)</p><p><code>EH</code> displays higher importance events</p><img src="'+y+'" style="zoom:75%;"><p><code>EL</code> displays lower importance events.</p><img src="'+b+'" style="zoom:75%;"><h3 id="libre-trend" tabindex="-1">Libre trend <a class="header-anchor" href="#libre-trend" aria-label="Permalink to &quot;Libre trend&quot;">​</a></h3><p>If you use a Libre sensor Show Libre Trend will display the last 45 minutes of sensor information, minute by minute.</p><img src="'+f+'" style="zoom:75%;"><h3 id="share-settings-via-qr-code" tabindex="-1">Share Settings via QR code <a class="header-anchor" href="#share-settings-via-qr-code" aria-label="Permalink to &quot;Share Settings via QR code&quot;">​</a></h3><p>This is a shortcut to Menu / Settings / <a href="./copysettings.html">Show Settings QR Code</a></p><h3 id="check-for-updated-version" tabindex="-1">Check for Updated Version <a class="header-anchor" href="#check-for-updated-version" aria-label="Permalink to &quot;Check for Updated Version&quot;">​</a></h3><p>This entry triggers a version check as defined in Menu / Settings / <a href="./update.html">xDrip Update Settings</a><br> If a new version is available it will open the download screen.</p><img src="'+w+'" style="zoom:75%;"><h3 id="send-feedback-to-developers" tabindex="-1">Send Feedback to Developers <a class="header-anchor" href="#send-feedback-to-developers" aria-label="Permalink to &quot;Send Feedback to Developers&quot;">​</a></h3><p>Only use this feature to send compliments.</p><p>For other enquiries prefer <a href="https://github.com/NightscoutFoundation/xDrip/discussions" target="_blank" rel="noreferrer">xDrip GitHub discussions</a> or <a href="https://www.facebook.com/groups/xDripG5" target="_blank" rel="noreferrer">Facebook</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Last modified 15/12/2024</em></a></p>',59)])])}const L=_(S,[["render",q]]);export{F as __pageData,L as default};
